normativeRecords.exactText:
VirtualDevice    { id, deviceName, poweredState: POWERED | UNPOWERED }
VirtualInterface { id, ownerDeviceId, providerModuleId?, name, address?, subnetId?, portClass, role, configuredState, runtimeState }
VirtualSubnet    { id, name, addressFamily, networkAddress, prefixLength }
VirtualPort      { id, ownerInterfaceId, name, configuredState, runtimeState }
VirtualLink      { id, endpointPortIds[2], configuredState, runtimeState }

Tag {
    id, name, scopeId, tableId, declaredTypeId,
    address?, comment, startValue, retainPolicy,
    displayFormat, constantValue?, hardwareChannelId?
}

BlockInterface {
    inputs[], outputs[], inOuts[], statics[], temps[], constants[], return?
}

body          = { statement }, EOF ;
statement     = assignment, ";"
              | call, ";"
              | "IF", expression, "THEN", { statement },
                { "ELSIF", expression, "THEN", { statement } },
                [ "ELSE", { statement } ], "END_IF", ";"
              | "CASE", expression, "OF", { case-arm },
                [ "ELSE", { statement } ], "END_CASE", ";"
              | "FOR", identifier, ":=", expression, "TO", expression,
                [ "BY", expression ], "DO", { statement }, "END_FOR", ";"
              | "WHILE", expression, "DO", { statement }, "END_WHILE", ";"
              | "REPEAT", { statement }, "UNTIL", expression, "END_REPEAT", ";"
              | "EXIT", ";" | "CONTINUE", ";" | "RETURN", ";" ;
case-arm      = case-label, { ",", case-label }, ":", { statement } ;
case-label    = constant-expression, [ "..", constant-expression ] ;
constant-expression = expression ;
assignment    = lvalue, ":=", expression ;
call          = designator, "(", [ argument, { ",", argument } ], ")" ;
argument      = [ identifier, ( ":=" | "=>" ) ], expression ;
expression    = or-expression ;
or-expression = xor-expression, { "OR", xor-expression } ;
xor-expression = and-expression, { "XOR", and-expression } ;
and-expression = compare-expression, { "AND", compare-expression } ;
compare-expression = add-expression,
                [ ( "=" | "<>" | "<" | "<=" | ">" | ">=" ), add-expression ] ;
add-expression = multiply-expression, { ( "+" | "-" ), multiply-expression } ;
multiply-expression = unary-expression, { ( "*" | "/" | "MOD" ), unary-expression } ;
unary-expression = { "+" | "-" | "NOT" }, postfix-expression ;
postfix-expression = primary, { ".", identifier | "[", expression,
                     { ",", expression }, "]" | call-suffix } ;
call-suffix    = "(", [ argument, { ",", argument } ], ")" ;
primary        = literal | identifier | "(", expression, ")" ;
designator     = identifier, { ".", identifier | "[", expression,
                 { ",", expression }, "]" } ;
lvalue         = designator ;
identifier     = ASCII letter or "_", followed by 0..127 ASCII letters, digits, or "_" ;
type-name      = identifier bound to a canonical primitive or named TypeId ;
non-time-type-name = type-name other than TIME or T ;
literal        = boolean | decimal-integer | based-integer | real | quoted | time-value
                 | non-time-type-name, "#", ( boolean | decimal-integer | based-integer | real | quoted ) ;
boolean        = "TRUE" | "FALSE" ;
decimal-integer = digit, { digit } ;
based-integer  = ( "2#", binary-digit, { binary-digit }
                 | "8#", octal-digit, { octal-digit }
                 | "16#", hex-digit, { hex-digit } ) ;
real           = digit, { digit }, ".", digit, { digit }, [ exponent ]
                 | digit, { digit }, exponent ;
exponent       = ( "E" | "e" ), [ "+" | "-" ], digit, { digit } ;
quoted         = "'", { CHAR except quote | "''" }, "'" ;
time-value     = ( "T#" | "TIME#" ), time-component, { time-component } ;
time-component = digit, { digit }, ( "d" | "h" | "m" | "s" | "ms" ) ;

BuildReport {
    attemptId, snapshotHash, requestedScope, expandedClosure,
    outcome, orderedDiagnostics, stageTimingsForDisplay,
    semanticFingerprint?, artifactFingerprint?, stale
}

BuildArtifact {
    artifactSchema, semanticFingerprint, packageFingerprint,
    verifiedTypedIr, hardwareArtifact, sourceMaps, probeTable,
    memorySchema, startValues, schedule, dependencyManifest,
    compilerAndProfileManifest, integrityHashes
}

SourceAnchor {
    ownerObjectId, sourceRevisionHash, language,
    semanticNodeId, textRange?, networkId?, nodeId?, portId?, edgeId?
}

VirtualIOBoundary {
    controllerId, schemaVersion,
    rawInputs[{channelId, typeId, canonicalValue, acceptedEventSequence}],
    deliveredOutputs[{
        channelId, typeId, canonicalValue, quality, suppressed,
        deliveryReason: RUN_OUTPUT_COMMIT | CPU_MODE_DEFAULT | FATAL_FAULT_DEFAULT | HARDWARE_SUPPRESSED,
        deliveryEventSequence, outputCommitScanSequence?
    }]
}

trigger     = or-term, EOF ;
or-term     = xor-term, { "OR", xor-term } ;
xor-term    = and-term, { "XOR", and-term } ;
and-term    = not-term, { "AND", not-term } ;
not-term    = { "NOT" }, predicate ;
predicate   = "TRUE" | "FALSE" | bool-channel
            | numeric-channel, comparator, contextual-numeric-literal
            | "(", or-term, ")" ;
comparator  = "=" | "<>" | "<" | "<=" | ">" | ">=" ;
bool-channel = channel-token bound to BOOL ;
numeric-channel = channel-token bound to an integer or floating trace channel ;
channel-token = "$", alias ;
alias       = ASCII letter or "_", followed by 0..63 ASCII letters, digits, or "_" ;
contextual-numeric-literal = [ "+" | "-" ], SCL decimal-integer, based-integer, or real token ;
